def finiteToRawSingularChain (K : Complex ι) (n : ℕ) :
    FiniteRationalChains K n →ₗ[ℚ] RawRationalChains K.space n :=
  (rationalToRawSingularChain K n).comp (rationalChainBasis K n).repr.symm.toLinearMap

